import { test } from "node:test";
import assert from "node:assert/strict";
import { setImmediate as tick } from "node:timers/promises";
import { labelsEndpoint, type LabelRequest } from "../src/shipping/labels.ts";
import { MemoryIdempotencyStore } from "../src/shipping/store.ts";
import { KEY_TTL_MS } from "../src/shipping/idempotency.ts";

function setup() {
    let now = Date.parse("2026-11-19T14:00:00Z");
    const carrier = {
        bought: [] as LabelRequest[],
        failNext: false,
        async buyLabel(req: LabelRequest) {
            await tick(); // the carrier API is slow
            await tick();
            if (this.failNext) {
                this.failNext = false;
                throw new Error("503 from carrier");
            }
            this.bought.push(req);
            return { trackingNumber: `1Z${String(this.bought.length).padStart(6, "0")}`, costCents: req.service === "express" ? 2400 : 890 };
        },
    };
    const charges: Record<string, number> = {};
    const accounts = { charge: async (id: string, cents: number) => void (charges[id] = (charges[id] ?? 0) + cents) };
    const post = labelsEndpoint(carrier, accounts, new MemoryIdempotencyStore(), () => now);
    return { carrier, charges, post, advance: (ms: number) => (now += ms) };
}

const parcel = { fromZip: "94107", toZip: "10001", weightGrams: 1200, service: "ground" };
const req = (key: string | undefined, body: unknown = parcel, accountId = "acme") => ({ accountId, headers: { "idempotency-key": key }, body });

test("a retried request gets the original label back without buying another", async () => {
    const { carrier, charges, post } = setup();
    const first = await post(req("scan-001"));
    const retry = await post(req("scan-001"));
    assert.equal(first.status, 201);
    assert.deepEqual(retry.body, first.body);
    assert.equal(retry.headers?.["Idempotent-Replayed"], "true");
    assert.equal(carrier.bought.length, 1);
    assert.deepEqual(charges, { acme: 890 });
});

test("two copies of the same request sent at once buy and bill one label", async () => {
    const { carrier, charges, post } = setup();
    const responses = await Promise.all([post(req("scan-002")), post(req("scan-002"))]);
    console.log("statuses:", responses.map((r) => r.status), "labels bought:", carrier.bought.length, "charged:", charges);
    assert.equal(carrier.bought.length, 1);
    assert.deepEqual(charges, { acme: 890 });
});

test("a duplicate that arrives while the first request is running is told to retry", async () => {
    const { post } = setup();
    const first = post(req("scan-003"));
    const duplicate = await post(req("scan-003"));
    assert.equal(duplicate.status, 409);
    assert.equal(duplicate.headers?.["Retry-After"], "1");
    assert.equal((await first).status, 201);
    assert.equal((await post(req("scan-003"))).headers?.["Idempotent-Replayed"], "true");
});

test("reusing a key with a different parcel is rejected", async () => {
    const { carrier, post } = setup();
    await post(req("scan-004"));
    const res = await post(req("scan-004", { ...parcel, service: "express" }));
    assert.equal(res.status, 422);
    assert.equal(carrier.bought.length, 1);
});

test("a carrier outage doesn't use up the key, so the scanner's retry succeeds", async () => {
    const { carrier, charges, post } = setup();
    carrier.failNext = true;
    assert.equal((await post(req("scan-005"))).status, 502);
    assert.equal((await post(req("scan-005"))).status, 201);
    assert.deepEqual(charges, { acme: 890 });
});

test("keys are per account and expire after 24 hours", async () => {
    const { carrier, charges, post, advance } = setup();
    await post(req("scan-006", parcel, "acme"));
    await post(req("scan-006", parcel, "globex"));
    assert.deepEqual(charges, { acme: 890, globex: 890 });
    advance(KEY_TTL_MS);
    assert.equal((await post(req("scan-006"))).headers?.["Idempotent-Replayed"], undefined);
    assert.equal(carrier.bought.length, 3);
});

test("requests without a key or with a bad parcel are rejected before anything is bought", async () => {
    const { carrier, post } = setup();
    assert.equal((await post(req(undefined))).status, 400);
    assert.equal((await post(req("scan-007", { ...parcel, toZip: "1000" }))).status, 400);
    assert.equal((await post(req("scan-008", { ...parcel, weightGrams: 0 }))).status, 400);
    assert.equal(carrier.bought.length, 0);
});
